//! The license dialog opened from Settings: RC2FX's own license and every
//! third-party notice, as generated by release packaging and checked by
//! `build.rs`. Collapsible sections with cached, virtualized rich text.

mod schema;
#[cfg_attr(not(test), allow(dead_code))]
mod source;

use super::*;
use gpui_kit::base::text::{TextView, TextViewState, TextViewStyle};
use gpui_kit::component::{WindowExt, dialog::DialogFooter};
use schema::Section;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

const EMBEDDED: &str = include_str!(concat!(env!("OUT_DIR"), "/licenses.json"));

/// The embedded sections, parsed once. `build.rs` already refused an invalid
/// file, so a failure here means a broken build; say so instead of panicking.
pub(super) fn sections() -> &'static [Section] {
    static SECTIONS: OnceLock<Vec<Section>> = OnceLock::new();
    SECTIONS.get_or_init(|| {
        schema::parse(EMBEDDED).unwrap_or_else(|e| {
            vec![Section {
                title: "Licenses unavailable".into(),
                text: format!("The license text in this build could not be read: {e}"),
            }]
        })
    })
}

// License sources are plain text, not Markdown. Escape punctuation and leading
// whitespace so legal notices cannot turn into headings, links, HTML or images.
// Small blocks let TextView virtualize even notices with no blank paragraphs.
fn notice_markdown(text: &str) -> String {
    let mut result = String::with_capacity(text.len() * 2);
    for (index, line) in text.lines().enumerate() {
        if index > 0 {
            result.push_str(if index % 32 == 0 { "\n\n" } else { "\\\n" });
        }
        if line.is_empty() {
            result.push_str("&#32;");
        }
        let mut leading = true;
        for ch in line.chars() {
            match ch {
                ' ' if leading => result.push_str("&#32;"),
                '\t' if leading => result.push_str("&#9;"),
                ch => {
                    leading = false;
                    if ch.is_ascii_punctuation() {
                        result.push('\\');
                    }
                    result.push(ch);
                }
            }
        }
    }
    result
}

#[derive(Default)]
struct LicensesView {
    expanded: BTreeSet<usize>,
    // Lazily parsed once per opened section; retain selection and scroll on
    // collapse/reopen instead of reconstructing thousands of rows each frame.
    text_views: BTreeMap<usize, Entity<TextViewState>>,
}

impl Render for LicensesView {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let mut list = div()
            .id("licenses-list")
            .v_flex()
            .gap_1()
            .max_h(px(440.))
            .overflow_y_scroll();
        for (index, section) in sections().iter().enumerate() {
            let open = self.expanded.contains(&index);
            let text_view = open.then(|| {
                self.text_views
                    .entry(index)
                    .or_insert_with(|| {
                        let markdown = notice_markdown(&section.text);
                        cx.new(|cx| TextViewState::markdown(&markdown, cx))
                    })
                    .clone()
            });
            list = list.child(
                div()
                    .v_flex()
                    .border_b_1()
                    .border_color(rgb(surface().line))
                    .child(
                        // A button, so the header is reachable by keyboard.
                        Button::new(("license-section", index))
                            .ghost()
                            .w_full()
                            .justify_start()
                            .label(format!(
                                "{} {}",
                                if open { "▾" } else { "▸" },
                                section.title
                            ))
                            .on_click(cx.listener(move |view, _, _, cx| {
                                if !view.expanded.remove(&index) {
                                    view.expanded.insert(index);
                                }
                                cx.notify();
                            })),
                    )
                    .when_some(text_view, |d, state| d.child(notice_box(&state, cx))),
            );
        }
        list
    }
}

/// Same selectable rich-text component as update notices, with its own bounded
/// viewport. Only visible blocks participate in repeated layout and painting.
fn notice_box(state: &Entity<TextViewState>, cx: &App) -> impl IntoElement {
    let style = TextViewStyle::from_theme(&gpui_kit::base::Theme::global(cx))
        .with_foreground(rgb(MUTED).into())
        .with_paragraph_gap(rems(0.));
    div()
        .h(px(320.))
        .flex_shrink_0()
        .my_2()
        .p(px(18.))
        .rounded(px(12.))
        .bg(rgb(surface().sunken))
        .border_1()
        .border_color(rgb(surface().line))
        .text_size(px(13.5))
        .child(
            TextView::new(state)
                .style(style)
                .selectable(true)
                .scrollable(true)
                .on_link_click(|_, _, _, _| {}),
        )
}

/// Open the license dialog over the current page. It changes nothing else:
/// drafts, connection and window stay as they are.
pub(super) fn open(window: &mut Window, cx: &mut App) {
    let view = cx.new(|_| LicensesView {
        // A single section (such as the development placeholder) starts open.
        expanded: if sections().len() == 1 {
            BTreeSet::from([0])
        } else {
            BTreeSet::new()
        },
        ..Default::default()
    });
    window.open_dialog(cx, move |dialog, _, _| {
        dialog
            .w(px(720.))
            .rounded(px(20.))
            .p_6()
            .bg(rgb(surface().panel))
            .border_1()
            .border_color(rgb(surface().line_strong))
            .text_color(rgb(TEXT))
            .font_family("Inter")
            .title(div().text_xl().font_semibold().child("Licenses"))
            .child(view.clone())
            .footer(DialogFooter::new().pt_5().child(
                gpui_kit::component::dialog::DialogClose::new().trigger(|button| {
                    button
                        .ghost()
                        .large()
                        .h(px(44.))
                        .px_5()
                        .rounded(px(22.))
                        .label("Close")
                }),
            ))
    });
}

#[cfg(test)]
mod tests {
    use super::schema::parse;
    use super::source::{PLACEHOLDER, resolve};
    use super::*;
    use std::io::Write;

    #[test]
    #[ignore = "local rendering measurement with the release notices bundle"]
    fn measure_license_redraws() {
        let mut app = gpui_test::TestApp::new();
        app.update(gpui_kit::init);
        let mut window = app.open_window(|_, _| LicensesView {
            expanded: (0..sections().len()).collect(),
            ..Default::default()
        });
        let start = std::time::Instant::now();
        window.draw();
        eprintln!("first draw: {:?}", start.elapsed());
        app.run_until_parked();
        window.draw();
        window.read(|view, cx| {
            for (index, state) in &view.text_views {
                assert_eq!(
                    normalise(state.read(cx).rendered_text().as_str()),
                    normalise(&sections()[*index].text)
                );
            }
        });
        let start = std::time::Instant::now();
        for _ in 0..10 {
            window.update(|_, _, cx| cx.notify());
            window.draw();
        }
        eprintln!("ten redraws: {:?}", start.elapsed());
    }

    fn normalise(text: &str) -> String {
        text.lines()
            .map(str::trim_end)
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn assert_same_text(actual: &str, expected: &str) {
        let actual = actual.trim_end();
        let expected = expected.trim_end();
        for (i, (a, b)) in actual.lines().zip(expected.lines()).enumerate() {
            assert_eq!(a, b, "line {i}");
        }
        assert_eq!(actual.len(), expected.len());
    }

    struct NoticeRoot(Entity<TextViewState>);
    impl Render for NoticeRoot {
        fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            div().w(px(640.)).child(notice_box(&self.0, cx))
        }
    }

    #[test]
    fn long_notices_keep_a_bounded_viewport_and_copy_the_entire_text() {
        let text = (0..7000)
            .map(|i| format!("Copyright holder {i}: All rights reserved.\n"))
            .collect::<String>();
        let mut app = gpui_test::TestApp::new();
        app.update(gpui_kit::init);
        let mut window = app.open_window(|_, cx| {
            NoticeRoot(cx.new(|cx| TextViewState::markdown(&notice_markdown(&text), cx)))
        });
        app.run_until_parked();
        window.draw();
        window.draw();
        window.read(|view, cx| {
            let state = view.0.read(cx);
            assert_same_text(state.rendered_text().as_str(), text.trim_end());
            let list = state.list_state();
            assert!(list.item_count() > 100);
            assert!(list.viewport_bounds().size.height > px(0.));
            assert!(list.viewport_bounds().size.height <= px(320.));
            assert_eq!(
                list.item_is_below_viewport(list.item_count() - 1),
                Some(true)
            );
        });
        window.update(|view, _, cx| {
            view.0.update(cx, |state, cx| {
                state
                    .list_state()
                    .scroll_to_reveal_item(state.list_state().item_count() - 1);
                state.select_all(cx);
            })
        });
        window.draw();
        window.read(|view, cx| {
            let state = view.0.read(cx);
            let list = state.list_state();
            assert!(list.logical_scroll_top().item_ix > 0);
            assert_eq!(
                list.item_is_below_viewport(list.item_count() - 1),
                Some(false)
            );
            assert_same_text(&state.selected_text(), text.trim_end());
        });
    }

    #[test]
    fn license_words_and_markup_characters_survive_rich_text_rendering() {
        let text = "# License <AUTHORS> & copyright ©\n\n    * This is not emphasis or code.\n1. [text](https://example.com)\n![image](https://example.com/image.png)\n<script>hello</script>\n`code` | ~~strike~~ \\ slash\n\tIndented notice";
        let mut app = gpui_test::TestApp::new();
        app.update(gpui_kit::init);
        let mut window = app.open_window(|_, cx| {
            NoticeRoot(cx.new(|cx| TextViewState::markdown(&notice_markdown(text), cx)))
        });
        window.draw();
        window.update(|view, _, cx| view.0.update(cx, |state, cx| state.select_all(cx)));
        window.read(|view, cx| {
            let state = view.0.read(cx);
            assert_eq!(normalise(state.rendered_text().as_str()), text);
            assert_eq!(normalise(&state.selected_text()), text);
        });
    }

    #[test]
    fn sections_parse_lazily_and_keep_selection_when_reopened() {
        let mut app = gpui_test::TestApp::new();
        app.update(gpui_kit::init);
        let mut window = app.open_window(|_, _| LicensesView::default());
        window.draw();
        window.read(|view, _| assert!(view.text_views.is_empty()));
        window.update(|view, _, cx| {
            view.expanded.insert(0);
            cx.notify();
        });
        window.draw();
        app.run_until_parked();
        let original = window.read(|view, _| view.text_views[&0].clone());
        window.update(|view, _, cx| {
            original.update(cx, |state, cx| state.select_all(cx));
            view.expanded.clear();
            cx.notify();
        });
        window.draw();
        window.update(|view, _, cx| {
            view.expanded.insert(0);
            cx.notify();
        });
        window.draw();
        window.read(|view, cx| {
            assert_eq!(view.text_views.len(), 1);
            assert_eq!(view.text_views[&0].entity_id(), original.entity_id());
            assert_same_text(
                &normalise(&original.read(cx).selected_text()),
                &normalise(&sections()[0].text),
            );
        });
    }

    #[test]
    fn the_embedded_bundle_parses() {
        assert!(!super::schema::parse(super::EMBEDDED).unwrap().is_empty());
    }

    #[test]
    fn a_valid_bundle_parses_in_order() {
        let s = parse(r#"{"schemaVersion":1,"sections":[{"title":"RC2FX","text":"MIT"},{"title":"serde","text":"MIT OR Apache-2.0"}]}"#).unwrap();
        assert_eq!(s.len(), 2);
        assert_eq!(
            (s[0].title.as_str(), s[1].text.as_str()),
            ("RC2FX", "MIT OR Apache-2.0")
        );
    }

    #[test]
    fn malformed_bundles_are_refused() {
        for bad in [
            "",
            "not json",
            "[]",
            r#"{"sections":[{"title":"a","text":"b"}]}"#,
            r#"{"schemaVersion":2,"sections":[{"title":"a","text":"b"}]}"#,
            r#"{"schemaVersion":"1","sections":[{"title":"a","text":"b"}]}"#,
            r#"{"schemaVersion":1}"#,
            r#"{"schemaVersion":1,"sections":[]}"#,
            r#"{"schemaVersion":1,"sections":[{"title":"a"}]}"#,
            r#"{"schemaVersion":1,"sections":[{"title":" ","text":"b"}]}"#,
            r#"{"schemaVersion":1,"sections":[{"title":"a","text":1}]}"#,
            r#"{"schemaVersion":1,"sections":[{"title":"a","text":"b","x":1}]}"#,
            r#"{"schemaVersion":1,"sections":[{"title":"a","text":"b"}],"extra":true}"#,
            r#"{"schemaVersion":1,"sections":["a"]}"#,
        ] {
            assert!(parse(bad).is_err(), "accepted {bad:?}");
        }
    }

    #[test]
    fn the_placeholder_is_valid_and_says_it_is_not_the_notices() {
        let s = parse(PLACEHOLDER).unwrap();
        assert_eq!(s.len(), 1);
        assert!(s[0].title.contains("not bundled"));
    }

    #[test]
    fn development_builds_without_a_file_get_the_placeholder() {
        assert_eq!(resolve(false, None).unwrap(), PLACEHOLDER);
    }

    #[test]
    fn release_builds_need_a_valid_file() {
        assert!(
            resolve(true, None)
                .unwrap_err()
                .contains("RC2FX_LICENSES_JSON")
        );
        let dir = tempfile::tempdir().unwrap();
        let missing = dir.path().join("missing.json");
        assert!(
            resolve(true, Some(&missing))
                .unwrap_err()
                .contains("cannot read")
        );
        assert!(
            resolve(false, Some(&missing)).is_err(),
            "a named file must exist"
        );
        let bad = dir.path().join("bad.json");
        std::fs::write(&bad, r#"{"schemaVersion":1,"sections":[]}"#).unwrap();
        assert!(
            resolve(true, Some(&bad))
                .unwrap_err()
                .contains("invalid license file")
        );
        let invalid_utf8 = dir.path().join("latin1.json");
        std::fs::File::create(&invalid_utf8)
            .unwrap()
            .write_all(b"{\"schemaVersion\":1,\"sections\":[{\"title\":\"\xff\",\"text\":\"\"}]}")
            .unwrap();
        assert!(resolve(true, Some(&invalid_utf8)).is_err());
        let good = dir.path().join("good.json");
        let text = r#"{"schemaVersion":1,"sections":[{"title":"RC2FX","text":"MIT"}]}"#;
        std::fs::write(&good, text).unwrap();
        assert_eq!(resolve(true, Some(&good)).unwrap(), text);
    }
}
